// Golden round-trip tests for the generated WS event models (issue #48
// Tier 3). The fixture at test/fixtures/turn_terminal_event.json is
// GENERATED by the Go side (internal/comm/http/ws_schema_drift_test.go
// TestWSSchemaFixtureGolden -update): it is the real relay's flattened
// output of a marshaled agent.TurnTerminalEvent, so these tests prove the
// Dart generated model decodes the exact bytes the daemon emits.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:meept_ui/models/ws_events.dart';

void main() {
  group('TurnTerminalEvent golden round-trip (Go-captured fixture)', () {
    final fixtureFile = File('test/fixtures/turn_terminal_event.json');
    late Map<String, dynamic> fixture;

    setUpAll(() {
      expect(fixtureFile.existsSync(), isTrue,
          reason: 'missing test/fixtures/turn_terminal_event.json — '
              'regenerate with: go test ./internal/comm/http '
              '-run TestWSSchemaFixtureGolden -update');
      fixture =
          jsonDecode(fixtureFile.readAsStringSync()) as Map<String, dynamic>;
    });

    test('parses every frozen field with identical values', () {
      final event = TurnTerminalEvent.fromParse(fixture);

      expect(event.turnId, fixture['turn_id']);
      expect(event.conversationId, fixture['conversation_id']);
      expect(event.sessionId, fixture['session_id']);
      expect(event.status, fixture['status']);
      expect(event.reply, fixture['reply']);
      expect(event.durationMs, fixture['duration_ms']);
      expect(event.handlerCase, fixture['handler_case']);
      expect(event.taskId, fixture['task_id']);
      expect(event.intentType, fixture['intent_type']);
      expect(event.agentId, fixture['agent_id']);
      expect(event.classifiedBy, fixture['classified_by']);
      expect(event.model, fixture['model']);
      expect(event.type, WsEventTypes.agentProgress);
      expect(event.sourceTopic, fixture['source_topic']);
    });

    test('fixture carries the relay classification + terminal shape', () {
      expect(fixture['type'], WsEventTypes.agentProgress);
      expect(fixture['source_topic'], 'turn.terminal');
      // terminal-frame identification contract: BOTH keys non-empty
      expect(isTurnTerminalPayload(fixture), isTrue);
    });

    test('toJson -> fromParse round-trips losslessly for present fields', () {
      final event = TurnTerminalEvent.fromParse(fixture);
      final map = event.toJson();
      // Only compare keys the Go payload actually emitted: toJson writes
      // omitempty-marked fields only when non-empty (includeIfNull: false),
      // matching the daemon's wire discipline.
      for (final entry in map.entries) {
        if (!fixture.containsKey(entry.key)) continue;
        expect(entry.value, fixture[entry.key],
            reason: 'round-trip drift at ${entry.key}');
      }
      // Re-parse must reproduce the same typed values.
      final reparsed = TurnTerminalEvent.fromParse(map);
      expect(reparsed.turnId, event.turnId);
      expect(reparsed.conversationId, event.conversationId);
      expect(reparsed.sessionId, event.sessionId);
      expect(reparsed.status, event.status);
      expect(reparsed.reply, event.reply);
      expect(reparsed.error, event.error);
      expect(reparsed.durationMs, event.durationMs);
      expect(reparsed.handlerCase, event.handlerCase);
    });

    test('defaults hold for an ordinary progress frame (not terminal)', () {
      final progress = {
        'type': WsEventTypes.agentProgress,
        'session_id': 's1',
        'message': 'thinking...',
      };
      expect(isTurnTerminalPayload(progress), isFalse);
      final event = TurnTerminalEvent.fromParse(progress);
      expect(event.turnId, isEmpty);
      expect(event.status, isEmpty);
      expect(event.durationMs, 0);
    });

    test('failure-shaped terminal event parses error + status', () {
      final failed = TurnTerminalEvent.fromParse({
        'turn_id': 't2',
        'conversation_id': 'c2',
        'handler_case': 'task_dispatch',
        'status': TurnTerminalEvent.statusFailed,
        'reply': '',
        'error': 'provider exploded',
        'duration_ms': 99,
      });
      expect(failed.status, TurnTerminalEvent.statusFailed);
      expect(failed.error, 'provider exploded');
    });
  });

  group('ChatMessageEvent (relay-normalized shape)', () {
    test('parses the publishChatMessage + relay normalization guarantees',
        () {
      // Exactly what transformBusEventToWS emits for the chat_message topic
      // (handler.publishChatMessage payload + relay normalization: content
      // mirrors reply, role defaults, id = bus message ID, source_topic).
      final frame = {
        'role': 'assistant',
        'content': 'hello from the daemon',
        'session_id': 'session-chat-1',
        'conversation_id': 'conv-chat-1',
        'error': '',
        'id': 'msg-123',
        'timestamp': '2026-09-17T12:00:00Z',
        'source_topic': 'chat_message',
        'type': WsEventTypes.chatMessage,
      };
      final event = ChatMessageEvent.fromParse(frame);
      expect(event.sessionId, 'session-chat-1');
      expect(event.conversationId, 'conv-chat-1');
      expect(event.role, 'assistant');
      expect(event.content, 'hello from the daemon');
      expect(event.id, 'msg-123');
      expect(event.timestamp, '2026-09-17T12:00:00Z');
      expect(event.sourceTopic, 'chat_message');
      expect(event.type, WsEventTypes.chatMessage);
    });

    test('session_id falls back cleanly when absent (legacy frame)', () {
      final event = ChatMessageEvent.fromParse({'content': 'x'});
      expect(event.sessionId, isEmpty);
      expect(event.role, 'assistant'); // relay default mirrored
      expect(event.content, 'x');
    });

    test('toJson -> fromParse round-trips', () {
      const event = ChatMessageEvent(
        sessionId: 's9',
        content: 'hi',
        id: 'm9',
      );
      final reparsed = ChatMessageEvent.fromJson(event.toJson());
      expect(reparsed.sessionId, 's9');
      expect(reparsed.content, 'hi');
      expect(reparsed.id, 'm9');
      expect(reparsed.role, 'assistant');
    });
  });

  group('WsEventTypes constants mirror wsclass.String()', () {
    // Pinned against internal/comm/wsclass/wsclass.go — a rename there
    // fails the Go drift gate; a rename here fails THIS test only if the
    // daemon actually changed, which the Go gate catches first.
    test('exact wire strings', () {
      expect(WsEventTypes.chatMessage, 'chat_message');
      expect(WsEventTypes.agentProgress, 'agent_progress');
      expect(WsEventTypes.metricsUpdate, 'metrics_update');
      expect(WsEventTypes.jobUpdate, 'job_update');
      expect(WsEventTypes.planUpdate, 'plan_update');
      expect(WsEventTypes.event, 'event');
    });
  });

  group('WsEvent envelope', () {
    test('fromFlat extracts the type and keeps the payload', () {
      const frame = {
        'type': WsEventTypes.metricsUpdate,
        'cpu': 0.5,
      };
      final ev = WsEvent.fromFlat(frame);
      expect(ev.type, WsEventTypes.metricsUpdate);
      expect(ev.payload['cpu'], 0.5);
    });

    test('missing type degrades to empty string, not a throw', () {
      expect(WsEvent.fromFlat({}).type, isEmpty);
    });
  });
}
